  1	/* ============================================================
  2	   views/config-model-registry.js — Model Registry tab module
  3	   Section 4d-mr of the MCP Server Dashboard SPA
  4	   Depends on: API, UI, escapeHtml, configDirty (defined in config.js)
  5	   Must be loaded BEFORE config.js.
  6	   ============================================================ */
  7	
  8	/* ── Module-level state ──────────────────────────────────── */
  9	
 10	/* Module-level state for Model Registry tab.
 11	   mrModels:    working copy of the model list (may have edits / pending deletions).
 12	   mrOriginal:  snapshot loaded from the server — used for dirty comparison.
 13	   mrEditingId: id of the row currently in edit mode (null when none). */
 14	var mrModels    = null;
 15	var mrOriginal  = null;
 16	var mrEditingId = null;
 17	
 18	/* Slug validation regex — mirrors the server-side rule. */
 19	var MR_SLUG_REGEX = /^[a-z0-9]+(-[a-z0-9]+)*$/;
 20	
 21	/* ── Helpers ─────────────────────────────────────────────── */
 22	
 23	/** Derive a slug from a human-readable name. */
 24	function mrDeriveSlug(name) {
 25	  return (name || '')
 26	    .toLowerCase()
 27	    .replace(/\s+/g, '-')
 28	    .replace(/[^a-z0-9-]/g, '')
 29	    .replace(/-+/g, '-')
 30	    .replace(/^-|-$/g, '');
 31	}
 32	
 33	/** Validate a slug string.  Returns an error message or '' if valid. */
 34	function mrValidateSlug(slug) {
 35	  if (!slug) return 'Slug is required.';
 36	  if (slug === 'inherit') return 'The slug "inherit" is reserved.';
 37	  if (!MR_SLUG_REGEX.test(slug)) return 'Slug must be lowercase alphanumeric with hyphens (e.g. my-model).';
 38	  return '';
 39	}
 40	
 41	/** Deep-clone a models array so mutations do not affect the original snapshot. */
 42	function mrCloneModels(arr) {
 43	  return arr.map(function (m) { return Object.assign({}, m); });
 44	}
 45	
 46	/** Return true when the working copy has any unsaved changes vs the snapshot. */
 47	function mrHasChanges() {
 48	  if (!mrModels || !mrOriginal) return false;
 49	  if (mrModels.length !== mrOriginal.length) return true;
 50	  for (var i = 0; i < mrModels.length; i++) {
 51	    var a = mrModels[i];
 52	    var b = mrOriginal[i];
 53	    if (a.id !== b.id || a.name !== b.name || a.slug !== b.slug || a.cc_model !== b.cc_model || a._deleted !== b._deleted) return true;
 54	  }
 55	  return false;
 56	}
 57	
 58	/* ── Render helpers ──────────────────────────────────────── */
 59	
 60	/** Render the dirty indicator dot HTML for a field that has changed. */
 61	function mrDirtyDot(isDirty) {
 62	  return isDirty ? '<span class="mr-dirty-dot" title="Unsaved change"></span>' : '';
 63	}
 64	
 65	/** Render a single read-only model row. */
 66	function mrRenderRow(model) {
 67	  var orig = mrOriginal ? mrOriginal.find(function (o) { return o.id === model.id; }) : null;
 68	  var isNew      = !orig;
 69	  var isDeleted  = !!model._deleted;
 70	  var nameDirty  = orig && model.name     !== orig.name;
 71	  var slugDirty  = orig && model.slug     !== orig.slug;
 72	  var ccDirty    = orig && model.cc_model !== orig.cc_model;
 73	
 74	  var rowClass = 'mr-model-row' + (isDeleted ? ' mr-model-deleted' : '') + (isNew ? ' mr-model-new' : '');
 75	
 76	  return '<tr class="' + rowClass + '" data-id="' + escapeHtml(model.id) + '">' +
 77	    '<td>' + mrDirtyDot(nameDirty || isNew) + escapeHtml(model.name) + '</td>' +
 78	    '<td>' + mrDirtyDot(slugDirty || isNew) + '<code>' + escapeHtml(model.slug) + '</code></td>' +
 79	    '<td>' +
 80	      mrDirtyDot(ccDirty || isNew) +
 81	      '<span title="Claude Code model override. Use \'inherit\' to defer to your Claude Code model setting.">' +
 82	        escapeHtml(model.cc_model || 'inherit') +
 83	      '</span>' +
 84	    '</td>' +
 85	    '<td class="mr-row-actions">' +
 86	      (isDeleted
 87	        ? '<button class="btn btn-sm btn-secondary mr-restore-btn" data-id="' + escapeHtml(model.id) + '">Restore</button>'
 88	        : '<button class="btn btn-sm btn-secondary mr-edit-btn"    data-id="' + escapeHtml(model.id) + '">Edit</button>' +
 89	          '<button class="btn btn-sm btn-danger  mr-delete-btn"   data-id="' + escapeHtml(model.id) + '">Delete</button>'
 90	      ) +
 91	    '</td>' +
 92	  '</tr>';
 93	}
 94	
 95	/** Render the edit row for the model currently being edited. */
 96	function mrRenderEditRow(model) {
 97	  var orig = mrOriginal ? mrOriginal.find(function (o) { return o.id === model.id; }) : null;
 98	  var isNew      = !orig;
 99	  var nameDirty  = orig && model.name     !== orig.name;
100	  var slugDirty  = orig && model.slug     !== orig.slug;

101	  var ccDirty    = orig && model.cc_model !== orig.cc_model;
102	  var slugError  = mrValidateSlug(model.slug);
103	
104	  return '<tr class="mr-model-row mr-edit-row" data-id="' + escapeHtml(model.id) + '">' +
105	    '<td>' +
106	      mrDirtyDot(nameDirty || isNew) +
107	      '<input type="text" class="form-control mr-field-name" value="' + escapeHtml(model.name) + '" placeholder="Model name" data-id="' + escapeHtml(model.id) + '">' +
108	      '<p class="form-note mr-error-text mr-name-error" style="display:none;color:var(--color-danger);">Name is required.</p>' +
109	    '</td>' +
110	    '<td>' +
111	      mrDirtyDot(slugDirty || isNew) +
112	      '<input type="text" class="form-control mr-field-slug' + (slugError ? ' mr-field-error' : '') + '" value="' + escapeHtml(model.slug) + '" placeholder="model-slug" data-id="' + escapeHtml(model.id) + '">' +
113	      (slugError ? '<p class="form-note mr-error-text">' + escapeHtml(slugError) + '</p>' : '') +
114	    '</td>' +
115	    '<td>' +
116	      mrDirtyDot(ccDirty || isNew) +
117	      '<input type="text" class="form-control mr-field-cc" value="' + escapeHtml(model.cc_model || '') + '" placeholder="inherit" data-id="' + escapeHtml(model.id) + '">' +
118	      '<p class="form-note">Claude Code model override. Use <code>inherit</code> to defer to your Claude Code model setting.</p>' +
119	    '</td>' +
120	    '<td class="mr-row-actions">' +
121	      '<button class="btn btn-sm btn-primary mr-save-row-btn" data-id="' + escapeHtml(model.id) + '"' + (slugError ? ' disabled' : '') + '>Done</button>' +
122	      '<button class="btn btn-sm btn-secondary mr-cancel-edit-btn" data-id="' + escapeHtml(model.id) + '">Cancel</button>' +
123	    '</td>' +
124	  '</tr>';
125	}
126	
127	/* ── Main render function ────────────────────────────────── */
128	
129	function renderModelRegistryTab(models) {
130	  /* Initialise local state from the server data on first render, or after
131	     a successful save.  If state is already populated we keep it (the user
132	     may have unsaved edits when re-rendering the tab, e.g. after a dirty-
133	     state guard was skipped). */
134	  if (mrModels === null) {
135	    mrModels   = mrCloneModels(models || []);
136	    mrOriginal = mrCloneModels(models || []);
137	    mrEditingId = null;
138	  }
139	
140	  return mrBuildTabHtml();
141	}
142	
143	/** (Re-)render the tab content and re-wire all event handlers. */
144	function mrRefreshTab() {
145	  var contentEl = document.getElementById('config-tab-content');
146	  if (!contentEl) return;
147	  contentEl.innerHTML = mrBuildTabHtml();
148	  mrWireEvents();
149	  /* Sync dirty flag */
150	  configDirty.modelRegistry = mrHasChanges();
151	}
152	
153	/** Build the full HTML string for the Model Registry tab. */
154	function mrBuildTabHtml() {
155	  var hasValidationErrors = mrModels
156	    ? mrModels.some(function (m) { return !m._deleted && mrValidateSlug(m.slug) !== ''; })
157	    : false;
158	
159	  /* Table rows */
160	  var rows = '';
161	  if (!mrModels || mrModels.length === 0) {
162	    rows = '<tr><td colspan="4" style="text-align:center;color:var(--color-text-muted);padding:24px;">No models registered. Add one below or click "Load Defaults".</td></tr>';
163	  } else {
164	    rows = mrModels.map(function (m) {
165	      return (mrEditingId === m.id) ? mrRenderEditRow(m) : mrRenderRow(m);
166	    }).join('');
167	  }
168	
169	  var tableHtml =
170	    '<div class="table-wrapper" style="margin-bottom:20px;">' +
171	      '<table id="mr-table">' +
172	        '<thead><tr>' +
173	          '<th>Name</th>' +
174	          '<th>Slug</th>' +
175	          '<th>cc_model</th>' +
176	          '<th style="width:140px;"></th>' +
177	        '</tr></thead>' +
178	        '<tbody id="mr-tbody">' +
179	          rows +
180	        '</tbody>' +
181	      '</table>' +
182	    '</div>';
183	
184	  /* Add Model form */
185	  var addFormHtml =
186	    '<div class="mr-add-section">' +
187	      '<h3 class="mr-section-title">Add Model</h3>' +
188	      '<div class="mr-add-row">' +
189	        '<div class="form-group mr-add-field">' +
190	          '<label class="form-label" for="mr-add-name">Name</label>' +
191	          '<input type="text" id="mr-add-name" class="form-control" placeholder="e.g. Claude Opus 4">' +
192	        '</div>' +
193	        '<div class="form-group mr-add-field">' +
194	          '<label class="form-label" for="mr-add-slug">Slug</label>' +
195	          '<input type="text" id="mr-add-slug" class="form-control" placeholder="claude-opus-4">' +
196	          '<p id="mr-add-slug-error" class="form-note mr-error-text" style="display:none;"></p>' +
197	        '</div>' +
198	        '<div class="form-group mr-add-field">' +
199	          '<label class="form-label" for="mr-add-cc">cc_model</label>' +
200	          '<input type="text" id="mr-add-cc" class="form-control" value="inherit" placeholder="inherit">' +
201	          '<p class="form-note">Claude Code model override. Use <code>inherit</code> to defer to your Claude Code model setting.</p>' +
202	        '</div>' +
203	        '<div class="form-group mr-add-action">' +
204	          '<label class="form-label" style="visibility:hidden;">Action</label>' +
205	          '<button id="mr-add-btn" class="btn btn-primary">Add Model</button>' +
206	        '</div>' +
207	      '</div>' +
208	    '</div>';
209	
210	  /* Action bar */
211	  var saveDisabled = hasValidationErrors ? ' disabled title="Fix validation errors before saving"' : '';
212	  var actionBarHtml =
213	    '<div class="mr-action-bar">' +
214	      '<button id="mr-save-btn" class="btn btn-primary"' + saveDisabled + '>Save</button>' +
215	      '<button id="mr-load-defaults-btn" class="btn btn-secondary">Load Defaults</button>' +
216	      '<div id="mr-msg" style="display:inline-block;margin-left:12px;"></div>' +
217	    '</div>';
218	
219	  var inner = tableHtml + addFormHtml + actionBarHtml;
220	
221	  return UI.card('Model Registry', inner);
222	}
223	
224	/* ── Event wiring ────────────────────────────────────────── */
225	
226	/** Wire all interactive elements on the Model Registry tab. */
227	function mrWireEvents() {
228	  var tbody = document.getElementById('mr-tbody');
229	  if (tbody) {
230	    /* Edit button */
231	    tbody.addEventListener('click', function (e) {
232	      var btn = e.target.closest('.mr-edit-btn');
233	      if (btn) {
234	        mrEditingId = btn.getAttribute('data-id');
235	        mrRefreshTab();
236	        return;
237	      }
238	
239	      /* Cancel edit */
240	      var cancelBtn = e.target.closest('.mr-cancel-edit-btn');
241	      if (cancelBtn) {
242	        mrEditingId = null;
243	        mrRefreshTab();
244	        return;
245	      }
246	
247	      /* Done (save row) */
248	      var saveRowBtn = e.target.closest('.mr-save-row-btn');
249	      if (saveRowBtn) {
250	        var id = saveRowBtn.getAttribute('data-id');

251	        var row = document.querySelector('.mr-edit-row[data-id="' + id + '"]');
252	        if (row) {
253	          var nameInput = row.querySelector('.mr-field-name');
254	          var slugInput = row.querySelector('.mr-field-slug');
255	          var ccInput   = row.querySelector('.mr-field-cc');
256	          var newName   = nameInput ? nameInput.value.trim() : '';
257	          var newSlug   = slugInput ? slugInput.value.trim() : '';
258	          var newCc     = ccInput   ? ccInput.value.trim()   : 'inherit';
259	
260	          /* Empty-name guard: reject blank model names inline without a server round-trip */
261	          if (!newName) {
262	            var nameErrEl = row.querySelector('.mr-name-error');
263	            if (nameErrEl) nameErrEl.style.display = '';
264	            if (nameInput) nameInput.focus();
265	            return;
266	          }
267	
268	          var slugErr   = mrValidateSlug(newSlug);
269	          if (slugErr) return; /* button should be disabled, but guard anyway */
270	          var model = mrModels.find(function (m) { return m.id === id; });
271	          if (model) {
272	            model.name     = newName;
273	            model.slug     = newSlug;
274	            model.cc_model = newCc || 'inherit';
275	          }
276	        }
277	        mrEditingId = null;
278	        mrRefreshTab();
279	        return;
280	      }
281	
282	      /* Delete */
283	      var deleteBtn = e.target.closest('.mr-delete-btn');
284	      if (deleteBtn) {
285	        var delId = deleteBtn.getAttribute('data-id');
286	        var delModel = mrModels.find(function (m) { return m.id === delId; });
